function images = qn_d4_images(p)
% The eight parameter images generated by the three maps preceding (13).

p=p(:); a=p(1); b=p(2); c=p(3); d=p(4);
images=[a, a,  a,  a, -a, -a, -a, -a; ...
        b, b, -b, -b, -c, -c,  c,  c; ...
        c,-c,  c, -c, -b,  b, -b,  b; ...
        d,-d, -d,  d,  d, -d, -d,  d];
end
